// Fonts for the Open Graph card, inlined as base64 so the edge runtime never
// has to resolve a file path (which is what broke the build on Windows).
// Fraunces and JetBrains Mono, latin subset, weight 400, WOFF — the three
// formats Satori accepts are ttf, otf and woff, never woff2.

const FRAUNCES_400 =
  "";

const JETBRAINS_MONO_400 =
  "";

function decode(b64: string) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out.buffer;
}

export const ogFonts = [
  { name: "Fraunces", data: decode(FRAUNCES_400), weight: 400 as const, style: "normal" as const },
  { name: "JetBrains Mono", data: decode(JETBRAINS_MONO_400), weight: 400 as const, style: "normal" as const },
];
